effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float rad = radians(angle);
  vec2 dir = vec2(cos(rad), sin(rad));
  float d = dot(uv - 0.5, dir) + 0.5;
  float band = 1.0 - smoothstep(0.0, width, abs(d - position));
  band = band * band;
  vec3 col = c + sweepColor.rgb * band * intensity * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
